function orderCandidates(ballots: string[]): string {
  const k = ballots[0].length;
  const votes = (c: string, p: number) => ballots.filter(b => b[p] === c).length;
  return ballots[0].split("").sort((x, y) => {
    for (let p = 0; p < k; p++) {
      const d = votes(y, p) - votes(x, p);
      if (d !== 0) return d;
    }
    return x < y ? -1 : 1;
  }).join("");
}

