class Solution:
    def orderCandidates(self, ballots: List[str]) -> str:
        k = len(ballots[0])

        def key(c: str):
            return [-sum(1 for b in ballots if b[p] == c) for p in range(k)] + [c]

        return "".join(sorted(ballots[0], key=key))

