function orderCandidates(ballots: string[]): string {
  const k = ballots[0].length;
  const count = new Map<string, number[]>();
  for (const c of ballots[0]) count.set(c, new Array(k).fill(0));
  for (const b of ballots) for (let p = 0; p < k; p++) count.get(b[p])![p]++;
  return [...count.keys()].sort((x, y) => {
    const cx = count.get(x)!, cy = count.get(y)!;
    for (let p = 0; p < k; p++) if (cx[p] !== cy[p]) return cy[p] - cx[p];
    return x < y ? -1 : 1;
  }).join("");
}

