class Solution:
    def orderCandidates(self, ballots: List[str]) -> str:
        k = len(ballots[0])
        count = {c: [0] * k for c in ballots[0]}
        for b in ballots:
            for p, c in enumerate(b):
                count[c][p] += 1
        # negate counts so a plain ascending sort puts more votes first
        return "".join(sorted(count, key=lambda c: ([-v for v in count[c]], c)))

